"""Module 07 concepts: oscillators and the 555 timer (Floyd 9e Ch.16)."""
from lib import K
M = 'm07'
K('m07-barkhausen', M, ('Điều kiện dao động của mạch hồi tiếp', 'Feedback oscillator conditions'),
  ('Dao động = hồi tiếp dương với Av·B = 1 và độ lệch pha vòng 0° (hay 360°). Khởi động cần Av·B > 1 để dao động lớn lên từ nhiễu rồi bị giới hạn về 1.', 'Oscillation = positive feedback with Av·B = 1 and a loop phase shift of 0° (or 360°). Start-up needs Av·B > 1 so the oscillation grows from noise, then limits back to 1.'),
  facts=[('Av·B = 1 ,  φ(vòng) = 0° (360°)', ('Chỉ cần nguồn một chiều, không cần tín hiệu vào.', 'Only dc power is needed; no input signal.'))],
  steps=[('Kiểm pha vòng trước (0°), rồi tính Av cần có = 1/B.', 'Check the loop phase first (0°), then the gain needed = 1/B.'), ('Khởi động: chọn Av hơi lớn hơn 1/B.', 'Start-up: choose Av slightly above 1/B.')],
  traps=[('Lẫn “độ lợi vòng bằng 1” với “độ lợi bộ khuếch đại bằng 1”.', 'Mixing “loop gain = 1” with “amplifier gain = 1”.')],
  angles=[('B = 1/75: độ lợi tối thiểu để dao động?', 'B = 1/75: minimum gain to oscillate?'), ('Vì sao cần Av·B > 1 lúc khởi động?', 'Why is Av·B > 1 needed at start-up?')],
  topics=['Feedback oscillator conditions'], kw=['barkhausen', 'oscillation condition', 'loop gain', 'phase shift', 'start-up', 'positive feedback', 'sustained', 'feedback oscillator'], kwv=['điều kiện dao động', 'độ lợi vòng', 'lệch pha vòng', 'khởi động', 'hồi tiếp dương', 'mạch dao động'],
  src=['Floyd 9e §16–1, 16–2'], related=['m04-oscillation', 'm07-wien', 'm07-phase-shift'], chk='barkhausen')
K('m07-wien', M, ('Mạch dao động cầu Wien', 'Wien-bridge oscillator'),
  ('Mạch dao động RC dùng mạng hồi tiếp thông thấp–thông cao lead–lag; ở tần số cộng hưởng suy giảm B = 1/3 và pha 0°, nên cần độ lợi bằng 3.', 'An RC oscillator whose lead-lag feedback network has attenuation B = 1/3 and 0° phase at the resonant frequency, so it needs a gain of 3.'),
  facts=[('fr = 1/(2π·R·C)', ('Hai R bằng nhau và hai C bằng nhau.', 'Equal resistors and equal capacitors.')), ('B = 1/3 ,  Av = 3 (Rf = 2·Ri)', ('Khởi động: Av hơi lớn hơn 3.', 'For start-up Av is a little above 3.'))],
  steps=[('Chọn C rồi R = 1/(2π·fr·C).', 'Pick C then R = 1/(2π·fr·C).'), ('Đặt Rf/Ri hơi lớn hơn 2 để khởi động.', 'Set Rf/Ri a little above 2 for start-up.')],
  traps=[('Dùng độ lợi 29 (dịch pha) cho cầu Wien.', 'Using the phase-shift gain 29 for the Wien bridge.')],
  angles=[('Tần số của cầu Wien với R = 10 kΩ, C = 16 nF.', 'Frequency of a Wien bridge with R = 10 kΩ, C = 16 nF.'), ('Độ lợi tối thiểu của mạch.', 'Minimum gain of the circuit.')],
  topics=['RC oscillators'], kw=['wien', 'wien bridge', 'lead-lag', 'rc oscillator', 'fr', '1/(2πrc)', 'sine wave oscillator', 'gain of 3'], kwv=['cầu wien', 'wien', 'dao động rc', 'dao động sin', 'độ lợi bằng 3'],
  src=['Floyd 9e §16–3'], related=['m07-phase-shift', 'm07-barkhausen'], chk='wien')
K('m07-phase-shift', M, ('Mạch dao động dịch pha và twin-T', 'Phase-shift and twin-T oscillators'),
  ('Ba mạng RC mỗi mạng lệch 60° cho tổng 180°, cộng 180° của bộ khuếch đại đảo thành 360°; mỗi mạng làm suy giảm nên tổng B = 1/29.', 'Three RC sections shift 60° each for 180°, which with the inverting amplifier\'s 180° makes 360°; the sections attenuate, giving a total B = 1/29.'),
  facts=[('fr = 1/(2π√6·RC)', ('Với ba mạng RC bằng nhau.', 'For three identical RC sections.')), ('B = 1/29 ,  Rf = 29·Ri', ('Độ lợi tối thiểu 29.', 'Minimum gain 29.'))],
  steps=[('Tính fr bằng công thức rồi Rf = 29·Ri.', 'Compute fr from the formula, then Rf = 29·Ri.')],
  traps=[('Dùng 1/(2πRC) của cầu Wien.', 'Using the Wien-bridge 1/(2πRC).'), ('Quên √6 ở mẫu số.', 'Forgetting the √6 in the denominator.')],
  angles=[('R = 10 kΩ, C = 0,01 μF: tần số dao động dịch pha?', 'R = 10 kΩ, C = 0.01 μF: phase-shift oscillation frequency?'), ('Độ lợi tối thiểu để dao động.', 'Minimum gain to oscillate.')],
  topics=['RC oscillators'], kw=['phase-shift oscillator', 'phase shift oscillator', 'twin-t', 'three rc', '60 degrees', '180', 'gain of 29', '√6'], kwv=['dịch pha', 'dao động dịch pha', 'twin-t', 'ba mạng rc', '29'],
  src=['Floyd 9e §16–3'], related=['m07-wien'], chk='phaseshift')
K('m07-lc', M, ('Mạch dao động LC và thạch anh', 'LC and crystal oscillators'),
  ('Colpitts dùng hai tụ phân áp, Hartley dùng cuộn cảm có đầu giữa, Clapp là Colpitts có thêm tụ nối tiếp với cuộn cảm; thạch anh cộng hưởng nối tiếp hoặc song song cho độ ổn định tần số rất cao.', 'The Colpitts uses a two-capacitor divider, the Hartley a tapped inductor, the Clapp is a Colpitts with an extra series capacitor in the inductor branch; a crystal resonating in series or in parallel gives very high frequency stability.'),
  facts=[('Colpitts: fr = 1/(2π√(L·CT)) ,  CT = C1C2/(C1 + C2)', ('Hai tụ nối tiếp nhìn từ cuộn cảm.', 'Two capacitors in series seen by the coil.')), ('Av = C1/C2 (khởi động: Av > C1/C2)', ('B = C2/C1.', 'B = C2/C1.')), ('Hartley: fr = 1/(2π√(LT·C)) ,  LT = L1 + L2', ('Bỏ qua hỗ cảm.', 'Mutual inductance neglected.'))],
  steps=[('Tính CT (hoặc LT) trước rồi fr.', 'Compute CT (or LT) first, then fr.'), ('Lấy Av tối thiểu = C1/C2.', 'Take the minimum Av = C1/C2.')],
  traps=[('Cộng hai tụ thay vì ghép nối tiếp.', 'Adding the two capacitors instead of combining them in series.'), ('Nhầm Colpitts (tụ chia) với Hartley (cuộn chia).', 'Confusing Colpitts (split capacitor) with Hartley (split coil).')],
  angles=[('L = 1 mH, C1 = C2 = 100 pF: fr Colpitts?', 'L = 1 mH, C1 = C2 = 100 pF: Colpitts fr?'), ('Vì sao dùng thạch anh?', 'Why use a crystal?')],
  topics=['LC and crystal oscillators'], kw=['colpitts', 'hartley', 'clapp', 'lc oscillator', 'tank circuit', 'crystal', 'quartz', 'series resonance', 'parallel resonance', 'resonant'], kwv=['colpitts', 'hartley', 'clapp', 'dao động lc', 'mạch cộng hưởng', 'thạch anh', 'cộng hưởng'],
  src=['Floyd 9e §16–4'], related=['m07-barkhausen'], chk='lc')
K('m07-relaxation', M, ('Mạch dao động thư giãn', 'Relaxation oscillators'),
  ('Tụ nạp–xả qua điện trở giữa hai ngưỡng của bộ so sánh có hysteresis, cho sóng vuông (và tam giác nếu thêm tầng tích phân).', 'A capacitor charges and discharges through a resistor between the two thresholds of a comparator with hysteresis, giving a square wave (and a triangular wave when an integrator is added).'),
  facts=[('f = 1/(2·R·C·ln((1 + B)/(1 − B))) ,  B = R₂/(R₁ + R₂)', ('Op-amp, ngưỡng ±B·Vsat.', 'Op-amp with thresholds ±B·Vsat.')), ('V_UTP = (R3/R2)(+Vmax) ,  V_LTP = −(R3/R2)(Vmax)', ('Máy phát sóng tam giác.', 'Triangular-wave generator.'))],
  steps=[('Tìm hai ngưỡng từ hồi tiếp dương.', 'Find the two thresholds from the positive feedback.'), ('Thời gian nạp giữa hai ngưỡng cho nửa chu kỳ, chu kỳ gấp đôi.', 'The charge time between thresholds gives half a period; the period is twice that.')],
  traps=[('Dùng 0,693·RC của 555 cho mạch op-amp.', 'Using the 555 0.693·RC for the op-amp circuit.')],
  angles=[('Tần số của mạch thư giãn với B = 0,5.', 'Frequency of a relaxation oscillator with B = 0.5.')],
  topics=['Relaxation oscillators'], kw=['relaxation oscillator', 'square wave', 'triangular wave', 'integrator', 'schmitt', 'hysteresis', 'charge and discharge'], kwv=['dao động thư giãn', 'sóng vuông', 'sóng tam giác', 'nạp xả'],
  src=['Floyd 9e §16–5'], related=['m03-hysteresis', 'm03-integrator'], chk='relaxation')
K('m07-555-astable', M, ('IC 555 phi ổn và VCO', '555 astable and the VCO'),
  ('555 phi ổn tự dao động giữa hai ngưỡng 1/3 và 2/3 VCC của tụ; R1 và R2 đặt tần số và chu kỳ làm việc. Thêm điện áp điều khiển ở chân 5 thì thành VCO.', 'The astable 555 free-runs while the capacitor swings between 1/3 and 2/3 VCC; R1 and R2 set the frequency and duty cycle. Control voltage on pin 5 makes it a VCO.'),
  facts=[('f = 1,44/((R1 + 2R2)·Cext)', ('Chu kỳ T = 0,693(R1 + 2R2)C.', 'Period T = 0.693(R1 + 2R2)C.')), ('duty = (R1 + R2)/(R1 + 2R2)', ('Luôn > 50 % với mạch cơ bản.', 'Always > 50 % in the basic circuit.')), ('t_H = 0,693(R1 + R2)C ,  t_L = 0,693·R2·C', ('Thời gian mức cao và thấp.', 'High and low times.'))],
  steps=[('Cho f và duty: giải R1, R2 từ hai công thức.', 'Given f and duty: solve R1, R2 from the two formulas.'), ('Chọn Cext trước rồi tính điện trở.', 'Choose Cext first, then the resistors.')],
  traps=[('Quên duty = (R1 + R2)/(R1 + 2R2), không phải R1/(R1 + R2).', 'Forgetting duty = (R1 + R2)/(R1 + 2R2), not R1/(R1 + R2).'), ('Sai đơn vị nF/μF.', 'Unit slips between nF and μF.')],
  angles=[('R1 = 1 kΩ, R2 = 10 kΩ, C = 0,1 μF: f và duty?', 'R1 = 1 kΩ, R2 = 10 kΩ, C = 0.1 μF: f and duty?'), ('Thiết kế 555 phi ổn có f = 4 kHz.', 'Design an astable 555 for f = 4 kHz.')],
  topics=['The 555 timer'], kw=['555', 'astable', 'duty cycle', 'timer', 'r1', 'r2', 'cext', 'vco', 'voltage-controlled oscillator', 'pulse width', 'pwm'], kwv=['555', 'phi ổn', 'chu kỳ làm việc', 'ic định thời', 'vco', 'điều chế độ rộng xung', 'pwm'],
  src=['Floyd 9e §16–6'], related=['m07-555-monostable', 'm10-pwm'], chk='astable555')
